import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateAnnouncementHandler } from "../handlers/updateAnnouncementHandler";
import type { ApiError } from "../runtime/client";
import type { TeamPartition } from "../types/TeamPartition";
import type { UpdateSubTeamAnnouncementRequest } from "../types/UpdateSubTeamAnnouncementRequest";

type Data = Awaited<ReturnType<typeof updateAnnouncementHandler>>;
type Vars = { teamPk: TeamPartition; announcementId: string; body: UpdateSubTeamAnnouncementRequest };

export function useUpdateAnnouncement(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateAnnouncementHandler(vars.teamPk, vars.announcementId, vars.body),
    ...options,
  });
}
